 46	const RELEVANT_FILES = new Set([
 47	  "README.md", "readme.md", "README.rst", "package.json", "requirements.txt",
 48	  "Cargo.toml", "go.mod", "Gemfile", "build.gradle", "pom.xml",
 49	  "Dockerfile", "docker-compose.yml", "docker-compose.yaml",
 50	  ".env.example", "Makefile", "Procfile",
 51	]);
