 53	const IGNORE_DIRS = new Set([
 54	  "node_modules", ".next", "dist", "build", ".git", "vendor",
 55	  "__pycache__", ".venv", "venv", "target", "coverage", ".cache",
 56	  ".husky", ".idea", ".vscode", "out", ".turbo",
