 65	const FRAMEWORK_PATTERNS: Record<string, string[]> = {
 66	  "Next.js": ["next"],
 67	  "React": ["react"],
 68	  "Vue": ["vue"],
 69	  "Angular": ["@angular/core"],
 70	  "Svelte": ["svelte"],
 71	  "Express": ["express"],
 72	  "Fastify": ["fastify"],
 73	  "NestJS": ["@nestjs/core"],
 74	  "Django": [],  // detected from requirements.txt
 75	  "Flask": [],
 76	  "FastAPI": [],
 77	  "Tailwind CSS": ["tailwindcss"],
 78	  "Prisma": ["prisma", "@prisma/client"],
 79	  "Supabase": ["@supabase/supabase-js"],
