 84	function detectFrameworks(files: RepoFile[]): string[] {
 85	  const frameworks: string[] = [];
 86	
 87	  const packageJson = files.find((f) => f.path === "package.json");
 88	  if (packageJson) {
 89	    try {
 90	      const pkg = JSON.parse(packageJson.content);
 91	      const allDeps = {
 92	        ...(pkg.dependencies ?? {}),
 93	        ...(pkg.devDependencies ?? {}),
 94	      };
 95	      for (const [framework, packages] of Object.entries(FRAMEWORK_PATTERNS)) {
 96	        if (packages.some((p) => p in allDeps)) {
 97	          frameworks.push(framework);
 98	        }
 99	      }
100	    } catch { /* skip */ }
101	  }
102	
103	  // Python frameworks from requirements.txt
104	  const reqTxt = files.find((f) =>
105	    f.path === "requirements.txt" || f.path === "requirements/base.txt"
106	  );
107	  if (reqTxt) {
108	    const content = reqTxt.content.toLowerCase();
109	    if (content.includes("django")) frameworks.push("Django");
110	    if (content.includes("flask")) frameworks.push("Flask");
111	    if (content.includes("fastapi")) frameworks.push("FastAPI");
112	  }
113	
114	  return [...new Set(frameworks)];
115	}
