119	async function getHeaders(): Promise<Record<string, string>> {
120	  const headers: Record<string, string> = {
121	    Accept: "application/vnd.github.v3+json",
122	    "User-Agent": "EHL-Code-Review",
123	  };
124	  const token = await getSettingValue(SETTING_KEYS.GITHUB_TOKEN, process.env.GITHUB_TOKEN);
125	  if (token) {
126	    headers.Authorization = `Bearer ${token}`;
127	  }
