140	function isRelevantFile(path: string): boolean {
141	  const filename = path.split("/").pop() ?? "";
142	  if (RELEVANT_FILES.has(filename)) return true;
143	  return RELEVANT_EXTENSIONS.has(getExtension(path));
144	}
