146	export async function ingestRepo(
147	  repoUrl: string,
148	  tokenBudget: number = 50000,
149	  commitSha?: string
150	): Promise<IngestedRepo> {
151	  const parsed = parseGitHubRepo(repoUrl);
152	  if (!parsed) throw new Error("Invalid GitHub URL");
153	
154	  const { owner, repo } = parsed;
155	  const cleanRepo = repo.replace(/\.git$/, "");
156	  const headers = await getHeaders();
157	
158	  const captured = commitSha ? await downloadCapturedArchive({ request: path => fetch(new URL(path, "https://api.github.com"), { headers, redirect: "manual", signal: AbortSignal.timeout(15000) }) }, repoUrl, commitSha) : null;
159	  let defaultBranch = commitSha || "main";
160	  let treeItems: Array<{ path: string; type: string; size?: number }>;
161	  if (captured) {
162	    treeItems = [...captured].map(([path, content]) => ({ path, type: "blob", size: Buffer.byteLength(content) }));
163	  } else {
164	    const repoRes = await fetch(`https://api.github.com/repos/${owner}/${cleanRepo}`, { headers });
165	    if (!repoRes.ok) throw new Error(`GitHub API error: ${repoRes.status}`);
166	    defaultBranch = (await repoRes.json()).default_branch || "main";
167	    const treeRes = await fetch(`https://api.github.com/repos/${owner}/${cleanRepo}/git/trees/${defaultBranch}?recursive=1`, { headers });
168	    if (!treeRes.ok) throw new Error(`GitHub tree API error: ${treeRes.status}`);
169	    treeItems = (await treeRes.json()).tree ?? [];
170	  }
171	
172	  // Get commit count (from first page with per_page=1, read total from Link header)
173	  let commitCount = 0;
174	  try {
175	    const commitsRes = captured ? new Response(null, { status: 404 }) : await fetch(
176	      `https://api.github.com/repos/${owner}/${cleanRepo}/commits?per_page=1`,
177	      { headers }
178	    );
179	    if (commitsRes.ok) {
180	      const linkHeader = commitsRes.headers.get("link") ?? "";
181	      const lastMatch = linkHeader.match(/page=(\d+)>; rel="last"/);
182	      commitCount = lastMatch ? parseInt(lastMatch[1]) : 1;
183	    }
184	  } catch { /* skip */ }
185	
186	  // Analyze tree for metadata
187	  const allBlobs = treeItems.filter((i) => i.type === "blob");
188	  const languages: Record<string, number> = {};
189	  let hasReadme = false;
190	  let hasDockerfile = false;
191	  let hasTests = false;
192	  let hasCi = false;
193	
194	  for (const item of allBlobs) {
195	    if (isIgnoredPath(item.path)) continue;
196	
197	    const filename = item.path.split("/").pop() ?? "";
198	    const ext = getExtension(item.path);
199	    const size = item.size ?? 0;
200	
201	    // Language counting
202	    const lang = EXT_LANGUAGE[ext];
203	    if (lang) {
204	      const approxLoc = Math.max(1, Math.round(size / 40)); // ~40 bytes per line
205	      languages[lang] = (languages[lang] ?? 0) + approxLoc;
206	    }
207	
208	    // Feature detection
209	    if (filename.toLowerCase().startsWith("readme")) hasReadme = true;
210	    if (filename === "Dockerfile" || filename === "docker-compose.yml") hasDockerfile = true;
211	    if (item.path.includes(".github/workflows/")) hasCi = true;
212	    if (item.path.split("/").some((s) => TEST_DIRS.has(s))) hasTests = true;
213	  }
214	
215	  // Filter and download relevant files
216	  const relevantItems = allBlobs.filter((item) => {
217	    if (isIgnoredPath(item.path)) return false;
218	    if (!isRelevantFile(item.path)) return false;
219	    if (item.size && item.size > 50000) return false; // Skip files > 50KB
220	    return true;
221	  });
222	
223	  // Sort: manifest/config files first, then by size ascending
224	  const PRIORITY_FILES = new Set([
225	    "README.md", "readme.md", "package.json", "requirements.txt",
226	    "Cargo.toml", "go.mod", "Dockerfile", "tsconfig.json",
227	  ]);
228	
229	  relevantItems.sort((a, b) => {
230	    const aName = a.path.split("/").pop() ?? "";
231	    const bName = b.path.split("/").pop() ?? "";
232	    const aPriority = PRIORITY_FILES.has(aName) ? 0 : 1;
233	    const bPriority = PRIORITY_FILES.has(bName) ? 0 : 1;
234	    if (aPriority !== bPriority) return aPriority - bPriority;
235	    return (a.size ?? 0) - (b.size ?? 0);
236	  });
237	
238	  // Download files within token budget
239	  const files: RepoFile[] = [];
240	  let totalChars = 0;
241	  const charBudget = tokenBudget * 4; // ~4 chars per token
242	  let sampled = false;
243	
244	  for (const item of relevantItems) {
245	    if (totalChars >= charBudget) {
246	      sampled = true;
247	      break;
248	    }
249	
250	    try {
251	      let decoded: string;
252	      if (captured) decoded = captured.get(item.path) ?? "";
253	      else {
254	        const contentRes = await fetch(`https://api.github.com/repos/${owner}/${cleanRepo}/contents/${item.path}?ref=${defaultBranch}`, { headers });
255	        if (!contentRes.ok) continue;
256	        const contentData = await contentRes.json();
257	        if (contentData.encoding !== "base64") continue;
258	        decoded = Buffer.from(contentData.content, "base64").toString("utf-8");
259	      }
260	
261	      // Truncate large files
262	      if (decoded.length > 8000) {
263	        const lines = decoded.split("\n");
264	        if (lines.length > 200) {
265	          decoded = lines.slice(0, 200).join("\n") + "\n\n[TRUNCATED - showing first 200 lines]";
266	        }
267	      }
268	
269	      if (totalChars + decoded.length > charBudget) {
270	        sampled = true;
271	        decoded = decoded.slice(0, charBudget - totalChars);
272	      }
273	
274	      files.push({ path: item.path, content: decoded });
275	      totalChars += decoded.length;
276	    } catch {
277	      continue;
278	    }
279	  }
280	
281	  // Determine primary language
282	  const langEntries = Object.entries(languages).sort((a, b) => b[1] - a[1]);
283	  const primaryLanguage = langEntries[0]?.[0] ?? "Unknown";
284	  const totalLoc = langEntries.reduce((sum, [, loc]) => sum + loc, 0);
285	
286	  // Detect frameworks
287	  const frameworksDetected = detectFrameworks(files);
288	
289	  const metadata: RepoMetadata = {
290	    languages,
291	    total_loc: totalLoc,
292	    file_count: allBlobs.filter((i) => !isIgnoredPath(i.path)).length,
293	    commit_count: commitCount,
294	    has_readme: hasReadme,
295	    has_dockerfile: hasDockerfile,
296	    has_tests: hasTests,
297	    primary_language: primaryLanguage,
298	    frameworks_detected: frameworksDetected,
299	    token_count: Math.round(totalChars / 4),
300	    sampled,
301	  };
302	
303	  return { files, metadata };
304	}

