     5	export function readRepositoryZip(bytes: Uint8Array): Map<string, string> {
     6	  if (bytes.byteLength > CAPTURE_LIMITS.archiveBytes)
     7	    throw new Error("Repository archive exceeds download limit");
     8	  let expanded = 0,
     9	    count = 0;
    10	  const paths = new Set<string>();
    11	  const archive = unzipSync(bytes, {
    12	    filter: (file) => {
    13	      count++;
    14	      expanded += file.originalSize;
    15	      if (
    16	        count > CAPTURE_LIMITS.archiveFiles ||
    17	        expanded > CAPTURE_LIMITS.expandedBytes
    18	      )
    19	        throw new Error("Repository archive exceeds expansion limit");
    20	      const segments = file.name.split("/");
    21	      if (
    22	        file.name.startsWith("/") ||
    23	        segments.includes("..") ||
    24	        file.name.includes("\\") ||
    25	        /[\x00-\x1f]/.test(file.name)
    26	      )
    27	        throw new Error("Unsafe archive path");
    28	      const path = segments.slice(1).join("/");
    29	      if (paths.has(path)) throw new Error("Duplicate archive path");
    30	      paths.add(path);
    31	      // Reviews historically omit files larger than 50 KB. Never extract to disk.
    32	      return !file.name.endsWith("/") && file.originalSize <= 50000;
    33	    },
    34	  });
    35	  const files = new Map<string, string>();
    36	  for (const [name, bytes] of Object.entries(archive)) {
    37	    const path = name.split("/").slice(1).join("/");
    38	    if (path && !bytes.includes(0))
    39	      files.set(path, new TextDecoder().decode(bytes));
    40	  }
    41	  return files;
    42	}
