    44	export async function downloadCapturedArchive(
    45	  github: { request(path: string): Promise<Response> },
    46	  repoUrl: string,
    47	  sha: string,
    48	): Promise<Map<string, string>> {
    49	  if (!/^[a-f0-9]{40}$/.test(sha))
    50	    throw new Error("An exact commit SHA is required");
    51	  const { owner, repo } = strictRepository(repoUrl);
    52	  let response = await github.request(`/repos/${owner}/${repo}/zipball/${sha}`);
    53	  if (response.status === 302) {
    54	    const location = new URL(response.headers.get("location") ?? "");
    55	    if (
    56	      location.protocol !== "https:" ||
    57	      location.hostname !== "codeload.github.com"
    58	    )
    59	      throw new Error("Unexpected archive redirect");
    60	    // Signed archive URL: never forward the API Authorization header.
    61	    response = await fetch(location, {
    62	      redirect: "error",
    63	      signal: AbortSignal.timeout(60000),
    64	      cache: "no-store",
    65	    });
    66	  }
    67	  if (!response.ok || !response.body)
    68	    throw new Error("Could not download frozen repository archive");
    69	  const reader = response.body.getReader();
    70	  const chunks: Uint8Array[] = [];
    71	  let size = 0;
    72	  try {
    73	    for (;;) {
    74	      const { done, value } = await reader.read();
    75	      if (done) break;
    76	      size += value.byteLength;
    77	      if (size > CAPTURE_LIMITS.archiveBytes)
    78	        throw new Error("Repository archive exceeds download limit");
    79	      chunks.push(value);
    80	    }
    81	  } finally {
    82	    await reader.cancel();
    83	  }
    84	  const bytes = new Uint8Array(size);
    85	  let offset = 0;
    86	  for (const chunk of chunks) {
    87	    bytes.set(chunk, offset);
    88	    offset += chunk.byteLength;
    89	  }
    90	  return readRepositoryZip(bytes);
    91	}
