 64	function repositoryUrl(value: unknown): string | null {
 65	  if (typeof value !== "string") return null;
 66	  try {
 67	    const { owner, repo } = strictRepository(value);
 68	    return `https://github.com/${owner}/${repo}`;
 69	  } catch { return null; }
 70	}
