 72	function validSelection(value: RepositorySelection | undefined): value is RepositorySelection {
 73	  return !!value && !!repositoryUrl(value.repo_url) && Number.isSafeInteger(value.repository_id) && value.repository_id > 0 &&
 74	    typeof value.frozen_sha === "string" && /^[a-f0-9]{40}$/.test(value.frozen_sha) &&
 75	    typeof value.entire_required === "boolean" && Array.isArray(value.checkpoint_manifest) &&
 76	    value.checkpoint_manifest.every(ref => ref && typeof ref.ref === "string" &&
 77	      typeof ref.sha === "string" && /^[a-f0-9]{40}$/.test(ref.sha));
