 80	/** One source of truth for review inputs and repository links. New receipts
 81	 * always select accepted objects; a delayed/failed copy cannot select newer code.
 82	 * Only revision zero retains the historical mutable repository fallback. */
 83	export function selectSubmissionRepository(
 84	  submission: Submission,
 85	  fields: SubmissionFieldConfig[],
 86	  fieldKey?: string
 87	): SubmissionRepository | null {
 88	  const repositoryFields = fields.filter(field => field.type === "repo" && submission.fields[field.key]);
 89	  const primary = repositoryFields[0]?.key;
 90	  const key = fieldKey ?? primary;
 91	  const fork = repositoryUrl(submission.forkUrl?.replace(/\/tree\/[a-f0-9]{40}\/?$/, ""));
 92	
 93	  if ((submission.submissionRevision ?? 0) === 0) {
 94	    const lowerFields = Object.fromEntries(Object.entries(submission.fields).map(([name, value]) => [name.toLowerCase(), value]));
 95	    const original = key ? submission.fields[key] : lowerFields.repo || lowerFields.github || lowerFields.repository ||
 96	      Object.values(submission.fields).find(value => repositoryUrl(value));
 97	    const repoUrl = fork || repositoryUrl(original);
 98	    if (!repoUrl) return null;
 99	    return { repoUrl, commitSha: submission.snapshotSha || undefined,
100	      href: submission.forkUrl || original || repoUrl, missingFork: !fork };
101	  }
102	
103	  if (!key || !repositoryFields.some(field => field.key === key)) return null;
104	  const accepted = submission.repoSnapshots?.[key];
105	  if (!validSelection(accepted) || repositoryUrl(submission.fields[key])?.toLowerCase() !== accepted.repo_url.toLowerCase()) return null;
106	  // The existing fork_url/snapshot_sha columns describe only the primary repo.
107	  // Other fields must use their own accepted source commit, never that fork.
108	  const copied = key === primary && !!fork && submission.snapshotSha === accepted.frozen_sha;
109	  const repoUrl = copied ? fork : accepted.repo_url;
110	  return {
111	    repoUrl, commitSha: accepted.frozen_sha, checkpointRefs: accepted.checkpoint_manifest,
112	    href: `${repoUrl}/tree/${accepted.frozen_sha}`, missingFork: !copied,
113	  };
