127	export async function prepareSubmissionRepositories(
128	  fields: Record<string, string>, requirements: SubmissionRequirements,
129	): Promise<Record<string, RepositorySelection>> {
130	  // Participant paths never use the privileged settings client. The same bot
131	  // token must be configured in the web app and background worker.
132	  const token = process.env.GITHUB_TOKEN;
133	  const headers = { Accept: "application/vnd.github+json", ...(token ? { Authorization: `Bearer ${token}` } : {}) };
134	  const request = async (path: string) => {
135	    let response: Response;
136	    try {
137	      response = await fetch(`https://api.github.com${path}`, { headers, cache: "no-store", signal: AbortSignal.timeout(10_000) });
138	    } catch {
139	      throw new SubmissionVerificationError("GitHub verification could not finish. Please retry before the deadline.");
140	    }
141	    if ([401, 403, 429].includes(response.status) || response.status >= 500)
142	      throw new SubmissionVerificationError("GitHub verification is temporarily unavailable or rate limited. Please retry before the deadline.");
