198	  if (/not our ref|couldn't find remote ref|unadvertised object|not a valid object|reference is not a tree/i.test(text))
199	    return new GitHubFailure(
200	      "Accepted repository objects are no longer available",
201	      "access",
202	    );
203	  const permanent =
204	    /permission denied|authentication failed|could not read Username|repository not found|remote rejected|shallow update not allowed|non-fast-forward|protected branch|GH00[0-9]/i.test(
205	      text,
206	    );
207	  // Never persist raw Git stderr: it can contain private paths and credentials.
208	  return new GitHubFailure(
209	    permanent
210	      ? "Git transfer refused. Check bot access and destination policy."
211	      : "Git transfer failed; a bounded retry is scheduled.",
212	    permanent ? "configuration" : "transient",
