224	 *
225	 * Rubric mirrors the SOTA hackathon approach (HackerRank Orchestrate): ownership
226	 * language is the strongest discriminator between teams that understand what they
227	 * shipped and teams that merely narrated an agent. This is a BONUS signal; it
228	 * never feeds placement. Completeness/tamper-plausibility is itself soft: a fuller,
229	 * coherent history that aligns with the code is rewarded; gaps are noted, not
230	 * punished as cheating.
231	 *
232	 * Security: prompt text is fully user-controlled and a prime injection vector.
233	 * The prompts are wrapped as untrusted data and the model is told to treat any
234	 * embedded instructions as content to evaluate, never to obey.
235	 */
236	export function buildSessionHistoryPrompt(params: {
237	  challenge: Challenge;
238	  briefText: string | null;
239	  metadata: RepoMetadata;
240	  session: {
241	    checkpointCount: number;
242	    promptCount: number;
