283	    "technical_specificity": { "score": 0, "rationale": "1 sentence" },
284	    "iteration_verification": { "score": 0, "rationale": "1 sentence" },
285	    "edge_case_awareness": { "score": 0, "rationale": "1 sentence" }
286	  },
