     3	import { revalidatePath } from "next/cache";
     4	import { createClient } from "@/lib/supabase/server";
     5	import { createAdminClient } from "@/lib/supabase/admin";
     6	import { requireAdminAction, getActingUserId } from "@/lib/admin-auth";
     7	import { PLACEMENT_POINTS, PARTICIPATION_POINTS } from "@/lib/scoring";
     8	import { logEvent, logEventStrict } from "@/lib/event-log";
     9	import { validateJuryRanking } from "@/lib/jury-validation";
    10	
    11	// ─── Score generation helpers (shared by finalize + regenerate) ─────────────
    12	// Not exported: a "use server" module may only export async functions, and these
    13	// are internal building blocks reused by finalizeJuryVotes and
    14	// regenerateScoresFromFinalizedRankings so both produce identical scores.
    15	
    16	type RankingRow = { ranking: unknown };
    17	type AdminClient = ReturnType<typeof createAdminClient>;
    18	
    19	/** Average each team's placement across all jury rankings, best (lowest) first. */
    20	function aggregateTeamAverages(
    21	  rankings: RankingRow[]
    22	): Array<{ teamId: string; avgPlace: number; voteCount: number }> {
    23	  const teamPlacements: Record<string, number[]> = {};
    24	  for (const r of rankings) {
    25	    const rankingData = (r.ranking as Record<string, string>) ?? {};
    26	    for (const [place, teamId] of Object.entries(rankingData)) {
    27	      if (!teamPlacements[teamId]) teamPlacements[teamId] = [];
    28	      teamPlacements[teamId].push(parseInt(place));
    29	    }
    30	  }
    31	  return Object.entries(teamPlacements)
    32	    .map(([teamId, places]) => ({
    33	      teamId,
    34	      avgPlace: places.reduce((sum, p) => sum + p, 0) / places.length,
    35	      voteCount: places.length,
    36	    }))
    37	    .sort((a, b) => {
    38	      if (Math.abs(a.avgPlace - b.avgPlace) < 0.001) return b.voteCount - a.voteCount;
    39	      return a.avgPlace - b.avgPlace;
    40	    });
    41	}
    42	
    43	/**
    44	 * Build placement (top 5) + participation scores from jury rankings and upsert
    45	 * them. Preserves existing admin_override rows. Returns the count written, or an
    46	 * error string. Idempotent-ish: an upsert keyed (chapter_id, team_id).
    47	 */
    48	async function writeScoresFromRankings(
    49	  adminClient: AdminClient,
    50	  challengeId: string,
    51	  chapterId: string,
    52	  challengeName: string,
    53	  rankings: RankingRow[]
    54	): Promise<{ scoresWritten: number } | { error: string }> {
    55	  const teamAverages = aggregateTeamAverages(rankings);
    56	
    57	  const { data: submissions } = await adminClient
    58	    .from("submissions")
    59	    .select("team_id")
    60	    .eq("challenge_id", challengeId);
    61	
    62	  // Don't overwrite admin overrides.
    63	  const { data: existingOverrides } = await adminClient
    64	    .from("scores")
    65	    .select("team_id")
    66	    .eq("chapter_id", chapterId)
    67	    .eq("source", "admin_override");
    68	  const overriddenTeamIds = new Set(
    69	    (existingOverrides ?? []).map((s) => s.team_id as string)
    70	  );
    71	
    72	  const scoresToUpsert: Array<{
    73	    chapter_id: string;
    74	    team_id: string;
    75	    challenge_id: string;
    76	    challenge_name: string;
    77	    placement: number | null;
    78	    points: number;
    79	    source: string;
    80	    published: boolean;
    81	  }> = [];
    82	  const rankedTeamIds = new Set<string>();
    83	
    84	  for (let i = 0; i < Math.min(5, teamAverages.length); i++) {
    85	    const placement = i + 1;
    86	    const teamId = teamAverages[i].teamId;
    87	    rankedTeamIds.add(teamId);
    88	    if (overriddenTeamIds.has(teamId)) continue;
    89	    scoresToUpsert.push({
    90	      chapter_id: chapterId,
    91	      team_id: teamId,
    92	      challenge_id: challengeId,
    93	      challenge_name: challengeName,
    94	      placement,
    95	      points: PLACEMENT_POINTS[placement] || 0,
    96	      source: "jury",
    97	      published: false,
    98	    });
    99	  }
   100	
   101	  for (const sub of submissions ?? []) {
   102	    const teamId = sub.team_id as string;
   103	    if (!rankedTeamIds.has(teamId) && !overriddenTeamIds.has(teamId)) {
   104	      scoresToUpsert.push({
   105	        chapter_id: chapterId,
   106	        team_id: teamId,
   107	        challenge_id: challengeId,
   108	        challenge_name: challengeName,
   109	        placement: null,
   110	        points: PARTICIPATION_POINTS,
   111	        source: "jury",
   112	        published: false,
   113	      });
   114	    }
   115	  }
   116	
   117	  if (scoresToUpsert.length > 0) {
   118	    const { error } = await adminClient
   119	      .from("scores")
   120	      .upsert(scoresToUpsert, { onConflict: "chapter_id,team_id" });
   121	    if (error) return { error: `Failed to save scores: ${error.message}` };
   122	  }
   123	
   124	  return { scoresWritten: scoresToUpsert.length };
   125	}
