"""Prüft relative Markdown-Links und #Anker (GitHub-Slug-Regeln) in einem Repo."""
import os, re, subprocess, sys

root = sys.argv[1]
files = [f for f in subprocess.run(["git", "-C", root, "ls-files", "*.md"], capture_output=True, text=True, encoding="utf-8").stdout.splitlines()]
link_re = re.compile(r"(?<!!)\[[^\]]*\]\(([^)\s]+)\)")

def slug(h):
    h = h.strip().lower()
    h = re.sub(r"[^\w\- ]", "", h, flags=re.UNICODE)
    return h.replace(" ", "-")

def anchors(path):
    text = open(path, encoding="utf-8").read()
    text = re.sub(r"```.*?```", "", text, flags=re.S)
    out, seen = set(), {}
    for m in re.finditer(r"^#{1,6}\s+(.+?)\s*$", text, flags=re.M):
        s = slug(re.sub(r"[`*]", "", m.group(1)))
        n = seen.get(s, 0); seen[s] = n + 1
        out.add(s if n == 0 else f"{s}-{n}")
    return out

bad = 0
for f in files:
    text = open(os.path.join(root, f), encoding="utf-8").read()
    text = re.sub(r"```.*?```", "", text, flags=re.S)
    for target in link_re.findall(text):
        if re.match(r"^(https?:|mailto:)", target) or target == "#":
            continue
        path, _, frag = target.partition("#")
        dest = os.path.normpath(os.path.join(root, os.path.dirname(f), path)) if path else os.path.join(root, f)
        if path and not os.path.exists(dest):
            print(f"FEHLT   {f}: {target}"); bad += 1; continue
        if frag and dest.endswith(".md") and frag not in anchors(dest):
            print(f"ANKER   {f}: {target}"); bad += 1
print(f"{len(files)} Dateien geprüft, {bad} Probleme")

